body.script:
    const apkDatabase = [
        { name: "CapCut Pro Mod", category: "ভিдео এডিটর • Premium Unlocked", size: "124 MB", icon: "🎬", link: "https://shrinkme.io/capcutpro" },
        { name: "Alight Motion Pro", category: "গ্রাফিক্স ও অ্যানিমেশন • Pro Pack", size: "75 MB", icon: "💎", link: "https://shrinkme.io/alightpro" },
        { name: "PicsArt Premium", category: "ফটো এডিটর • All Features Open", size: "88 MB", icon: "🎨", link: "https://shrinkme.io/picsartpro" },
        { name: "Kinemaster Pro", category: "ভিдео এডিটর • No Watermark", size: "95 MB", icon: "✂️", link: "https://shrinkme.io/kinemaster" }
    ];
    function displayApps(apps) {
        const container = document.getElementById('store-apps-container');
        let html = '';
        if(apps.length === 0) {
            container.innerHTML = '
দুঃখিত! এই অ্যাপটি পাওয়া যায়নি।';
            return;
        }
        apps.forEach((app, index) => {
            html += `


${app.icon}

${app.name}
${app.category} (${app.size})
ডাউনলোড`;
        });
        container.innerHTML = html;
    }
    displayApps(apkDatabase);
    function searchAPK() {
        const query = document.getElementById('search-input').value.toLowerCase().trim();
        if(query === "") { displayApps(apkDatabase); return; }
        const filteredApps = apkDatabase.filter(app => app.name.toLowerCase().includes(query));
        displayApps(filteredApps);
    }
    function startTimer(index, downloadLink) {
        let timeLeft = 15;
        const btnContainer = document.getElementById(`btn-container-${index}`);
        const downloadInterval = setInterval(() => {
            if(timeLeft <= 0) {
                clearInterval(downloadInterval);
                btnContainer.innerHTML = `ফাইল রেডি`;
            } else {
                btnContainer.innerHTML = `অপেক্ষা করুন.. ${timeLeft}s`;
            }
            timeLeft -= 1;
        }, 1000);
    }
